    "konj_tid_r3_role": "ہم وقتیت",
    "konj_tid_r3_desc": "دو کام ایک ہی وقت میں متوازی طور پر رونما ہوتے ہیں۔",
    "konj_tid_r4_role": "زمانی ترتیب",
    "konj_tid_r4_desc": "Inden = پہلے۔ Efter at = بعد میں۔ Indtil = آخری حد تک۔",
    "konj_tid_q1_exp": "\"I går aftes\" ماضی میں ایک مخصوص بار ہے → \"Da\"!",
    "konj_tid_q2_exp": "\"I aften\" مستقبل میں ہے → مستقبل کے لیے ہمیشہ \"Når\" استعمال ہوتا ہے!",
    "konj_tid_q3_exp": "خبردار! اگرچہ یہ ماضی میں ہے (\"besøgte\")، لیکن یہ ہر بار ہوتا تھا (\"Altid når...\")۔ دہرائی جانے والی عادات میں \"når\" استعمال ہوتا ہے!",
    "konj_tid_q4_exp": "دادا دادی ماضی میں صرف ایک مسلسل مدت کے لیے جوان تھے → \"Da\"۔",
    "konj_tid_q5_exp": "کھانے کو چھونے سے پہلے ہاتھ دھونا ضروری ہیں → \"inden\"۔",
    "konj_tid_q6_exp": "کھیل اور کافی پینا ایک ہی وقت میں ساتھ ساتھ ہو رہے تھے → \"mens\"۔",
    "konj_tid_q7_exp": "انتظار کا وقت اس لمحے ختم ہوتا ہے جب ڈاکٹر بلاتا ہے → \"indtil\"۔",
    "konj_tid_q8_exp": "پہلے وہ آٹھ گھنٹے سویا، اور اس کے بعد اس نے تازگی محسوس کی → \"efter at\"۔",
    "konj_aarsag_intro_title": "\"Fordi\", \"for\", \"så\" یا \"derfor\"؟",
    "konj_aarsag_intro_desc": "دو باتوں کی جانچ کر کے اس روایتی الجھن کو حل کریں: 1) کیا دوسرا جملہ وجہ ہے یا نتیجہ؟ 2) الفاظ کی ترتیب کیسی ہے؟",
    "konj_aarsag_r1_role": "وجہ (ماتحت جملہ)",
    "konj_aarsag_r1_desc": "ماتحت جملہ: فاعل + ikke/aldrig + فعل۔",
    "konj_aarsag_r2_role": "وجہ (آزاد جملہ)",
    "konj_aarsag_r2_desc": "آزاد جملہ: فاعل + فعل + ikke/aldrig۔",
    "konj_aarsag_r3_role": "نتیجہ (آزاد جملہ)",
    "konj_aarsag_r3_desc": "آزاد جملہ: بغیر کسی inversion کے۔ فاعل + فعل۔",
    "konj_aarsag_r4_role": "نتیجہ (متعلق فعل)",
