    "konj_aarsag_q1_exp": "دوسرا جملہ وجہ ہے، اور \"ikke\" فعل سے پہلے ہے (\"det ikke er\") → \"fordi\" کے ساتھ ماتحت جملہ!",
    "konj_aarsag_q2_exp": "دوسرا جملہ وجہ ہے، لیکن اب \"ikke\" فعل کے بعد ہے (\"det er ikke\") → \"for\" کے ساتھ آزاد جملہ!",
    "konj_aarsag_q3_exp": "دوسرا جملہ نتیجہ ہے، اور فاعل (\"vi\") فعل (\"spiser\") سے پہلے ہے → آزاد جملے کا حرفِ عطف \"så\"!",
    "konj_aarsag_q4_exp": "دوسرا جملہ نتیجہ ہے، اور فعل (\"spiser\") فاعل (\"vi\") سے پہلے ہے → ربطی متعلق فعل \"Derfor\"!",
    "konj_aarsag_q5_exp": "وقت کا متعلق فعل \"aldrig\" امدادی فعل سے پہلے ہے (\"aldrig har\") → \"fordi\" کے ساتھ ماتحت جملہ!",
    "konj_aarsag_q6_exp": "امدادی فعل \"aldrig\" سے پہلے ہے (\"har aldrig\") → \"for\" کے ساتھ آزاد جملہ!",
    "konj_aarsag_q7_exp": "کوما کے بعد \"jeg kunne\" آتا ہے (فاعل فعل سے پہلے = کوئی inversion نہیں) → \"så\"!",
